<?php
require_once 'includes/components.php'; require_once 'config.php'; require_once 'booking_repository.php'; ensureBookingSchema($conn);
if(!isset($_SESSION['auth_user']['email'])){header('Location: auth.php');exit;} $id=(int)$_SESSION['auth_user']['id'];$email=$_SESSION['auth_user']['email'];$s=$conn->prepare('SELECT * FROM appointments WHERE user_id=? OR customer_email=? ORDER BY appointment_date DESC,appointment_time DESC');$s->bind_param('is',$id,$email);$s->execute();$items=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lịch hẹn của tôi | NALI</title><link rel="stylesheet" href="common.css"><link rel="stylesheet" href="theme.css"><link rel="stylesheet" href="content-pages.css"></head><body><?php renderHeader('contact');?><main class="content-wrap"><h1>Lịch hẹn của tôi</h1><p>Chỉ có thể hủy hoặc đổi lịch trước giờ hẹn ít nhất 4 giờ; lịch đã hoàn thành giữ lại làm lịch sử điều trị cơ bản.</p><?php if($items):?><table class="content-table"><thead><tr><th>Mã</th><th>Ngày giờ</th><th>Dịch vụ/ghi chú</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($items as $a):$eligible=in_array($a['status'],['pending','confirmed'],true)&&strtotime($a['appointment_date'].' '.$a['appointment_time'])>time()+14400;?><tr><td>#<?=$a['id']?></td><td><?=htmlspecialchars(date('d/m/Y H:i',strtotime($a['appointment_date'].' '.$a['appointment_time'])))?></td><td><?=htmlspecialchars($a['notes']??'—')?></td><td><?=htmlspecialchars($a['status'])?></td><td><?php if($eligible):?><button class="content-button secondary" onclick="cancelAppointment(<?=$a['id']?>)">Hủy lịch</button><a class="content-button" href="booking.php?reschedule=<?=$a['id']?>">Đổi lịch</a><?php else:?><small>Không thể tự đổi/hủy</small><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php else:?><div class="content-empty">Chưa có lịch hẹn. <a href="booking.php">Đặt lịch ngay</a></div><?php endif;?></main><?php renderFooter();?><script>async function cancelAppointment(id){if(!confirm('Hủy lịch hẹn này?'))return;let r=await fetch('appointment_action.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'cancel',id})}),d=await r.json();alert(d.message);if(d.success)location.reload()}</script></body></html>
